package dev.elpsy.ticket;
import dev.elpsy.ticket.inventory.*;
import dev.elpsy.ticket.orders.*;
import dev.elpsy.ticket.orders.OrderModels.*;
import dev.elpsy.ticket.common.ApiErrors.Problem;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.expiry.enabled=false","ticket.stock-recovery.enabled=false","ticket.stock-return.enabled=true","ticket.stock-return-recovery.enabled=true","ticket.stock-return-recovery.initial-delay-ms=3600000","ticket.admission.namespace=encore-demo-increment-return-queue"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockReturnRecoveryIntegrationTest {
 @Autowired ApplicationContext context;@Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;
 @Autowired StockReturnStaffService staff;@Autowired StockReturnRecoveryStore store;@Autowired StockReturnRecoveryWorker worker;
 @Autowired StockProjectionService projection;@Autowired StockSettlementService settlement;@Autowired PurchaseService purchases;@Autowired OrderService orders;@Autowired PlatformTransactionManager transactions;
 CommitCursorFixture fixtures;String manager="return-queue-"+UUID.randomUUID();Set<String> keys=new HashSet<>();
 record Original(CommitCursorFixture.Fixture f,UUID order,UUID request){}
 @BeforeAll void setup(){fixtures=new CommitCursorFixture(context);db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");}
 @AfterEach void cleanup()throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(db.queryForObject("SELECT count(*) FROM stock_return_recovery_job WHERE state IN ('WAITING','LEASED')",Integer.class)>0){var c=store.claim(1);if(c.isPresent())store.failed(c.get(),"TEST_CLEANUP",true);else{assertTrue(System.nanoTime()<until);Thread.sleep(100);}}redis.delete(keys);keys.clear();}
 Original original(){var f=fixtures.accepted(false);keys.add(fixtures.ledger.key(f.ticket(),1));keys.add(fixtures.experiment.cursorKey(f.ticket(),1));assertTrue(purchases.process(f.event()));assertEquals("COMMITTED",settlement.reconcile(f.intent()).resolution());var order=db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,f.intent());orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));return new Original(f,order,UUID.randomUUID());}
 StockReturnStaffService.Begin body(Original o){return new StockReturnStaffService.Begin(o.request(),3);}
 StockReturnStaffService.Receipt submit(Original o){keys.add(fixtures.ledger.key(o.f().ticket(),2));return staff.submit(manager,o.f().ticket(),o.order(),body(o));}
 Original pending(boolean closed){var o=original();db.execute("ALTER TABLE stock_return_staff_audit ADD CONSTRAINT queue_phase_fault CHECK(state<>'"+(closed?"APPLIED":"CLOSED")+"') NOT VALID");try{assertThrows(org.springframework.dao.DataAccessException.class,()->submit(o));}finally{db.execute("ALTER TABLE stock_return_staff_audit DROP CONSTRAINT queue_phase_fault");}assertEquals(closed?"CLOSED":"REGISTERED",staff.progress(manager,o.request()).state());return o;}
 void enroll(Original o){assertEquals("WAITING",store.enroll(manager,o.request(),body(o)).state());}
 int count(UUID request,String table){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE request_id=?",Integer.class,request);}
 void problem(String code,Runnable r){assertEquals(code,assertThrows(Problem.class,r::run).code);}
 @Test void registeredOriginalCompletesOneFreshGenerationWithExactAudit()throws Exception{var o=pending(false);enroll(o);var domain=StockReturnBaselineSeed.domainSha(db,o.f());var old=redis.opsForHash().entries(fixtures.ledger.key(o.f().ticket(),1));assertTrue(worker.run(store.claim(5).orElseThrow()));var j=store.read(manager,o.request());assertEquals("DONE",j.state());assertEquals(1,j.attempts());assertEquals("APPLIED",staff.progress(manager,o.request()).state());assertEquals(2,projection.inspect(o.f().ticket()).generation());assertEquals(1,count(o.request(),"stock_return_ack"));assertEquals(3,count(o.request(),"stock_return_recovery_audit"));assertEquals(1,count(o.request(),"stock_return_recovery_claim"));assertEquals(old,redis.opsForHash().entries(fixtures.ledger.key(o.f().ticket(),1)));assertEquals(domain,StockReturnBaselineSeed.domainSha(db,o.f()));}
 @Test void closedAfterRedisOpenResumesWithoutNewGenerationOrCredit(){var o=pending(true);enroll(o);var hash=redis.opsForHash().entries(fixtures.ledger.key(o.f().ticket(),2));assertTrue(worker.run(store.claim(5).orElseThrow()));assertEquals(hash,redis.opsForHash().entries(fixtures.ledger.key(o.f().ticket(),2)));assertEquals(2,projection.inspect(o.f().ticket()).generation());}
 @Test void enrollmentIsExactOwnerAndIdempotentEvenFlagOff(){var o=pending(false);var j=store.enroll(manager,o.request(),body(o));assertEquals(j,store.enroll(manager,o.request(),body(o)));var off=new StockReturnRecoveryStore(db,false);assertEquals("WAITING",off.enroll(manager,o.request(),body(o)).state());problem("REQUEST_CONFLICT",()->store.enroll(manager,o.request(),new StockReturnStaffService.Begin(o.request(),4)));var another=pending(false);problem("RETURN_RECOVERY_DISABLED",()->off.enroll(manager,another.request(),body(another)));assertEquals(1,count(o.request(),"stock_return_recovery_audit"));}
 @Test void terminalOriginalCannotNewEnrollOrAbsorbAutomatically(){var o=original();assertEquals("APPLIED",submit(o).state());problem("RETURN_TERMINAL",()->store.enroll(manager,o.request(),body(o)));var b=original();orders.place(b.f().owner(),new Place(UUID.randomUUID(),b.f().ticket(),1,1,1200));assertEquals("BLOCKED",submit(b).state());problem("RETURN_TERMINAL",()->store.enroll(manager,b.request(),body(b)));assertEquals(0,count(b.request(),"stock_return_resolution"));}
 @Test void ownerRoleAndOtherManagerAreCheckedBeforeEnrollment(){var o=pending(false);String other="queue-other-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),other,"unused hash","MANAGER");problem("NOT_FOUND",()->store.enroll(other,o.request(),body(o)));enroll(o);db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);try{assertEquals("WAITING",store.read(manager,o.request()).state());problem("FORBIDDEN",()->store.enroll(manager,o.request(),body(o)));assertTrue(worker.run(store.claim(5).orElseThrow()));assertEquals("ACTOR_FORBIDDEN",store.read(manager,o.request()).lastCode());assertEquals("REGISTERED",staff.progress(manager,o.request()).state());}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);}}
 @Test void sourceAdvanceStopsAtReviewNeverRetargets(){var o=pending(false);enroll(o);orders.place(o.f().owner(),new Place(UUID.randomUUID(),o.f().ticket(),1,1,1200));assertTrue(worker.run(store.claim(5).orElseThrow()));assertEquals("REVIEW",store.read(manager,o.request()).state());assertEquals("BLOCKED",staff.progress(manager,o.request()).state());assertEquals(1,projection.inspect(o.f().ticket()).generation());assertEquals(0,count(o.request(),"stock_return_ack"));assertEquals(0,count(o.request(),"stock_return_resolution_fence"));}
 @Test void auditFaultRetainsOriginalBodyAndDueBackoffThenRetries()throws Exception{var o=pending(true);enroll(o);db.execute("ALTER TABLE stock_return_staff_audit ADD CONSTRAINT queue_apply_fault CHECK(state<>'APPLIED') NOT VALID");try{assertTrue(worker.run(store.claim(5).orElseThrow()));assertEquals("PG_FAILURE",store.read(manager,o.request()).lastCode());assertEquals("WAITING",store.read(manager,o.request()).state());assertTrue(store.claim(5).isEmpty());assertEquals(0,count(o.request(),"stock_return_ack"));}finally{db.execute("ALTER TABLE stock_return_staff_audit DROP CONSTRAINT queue_apply_fault");}Thread.sleep(1100);assertTrue(worker.run(store.claim(5).orElseThrow()));assertEquals(2,store.read(manager,o.request()).attempts());assertEquals(1,count(o.request(),"stock_return_ack"));}
 @Test void concurrentClaimsChooseExactlyOneAttempt()throws Exception{var o=pending(false);enroll(o);try(var pool=Executors.newFixedThreadPool(4)){var tasks=new ArrayList<Callable<Optional<StockReturnRecoveryStore.Claim>>>();for(int i=0;i<4;i++)tasks.add(()->store.claim(5));var claimed=new ArrayList<StockReturnRecoveryStore.Claim>();for(var f:pool.invokeAll(tasks))f.get().ifPresent(claimed::add);assertEquals(1,claimed.size());assertTrue(worker.run(claimed.getFirst()));}assertEquals(1,count(o.request(),"stock_return_recovery_claim"));}
 @Test void expiredClaimCannotExecuteAndNewClaimContinuesOriginal()throws Exception{var o=pending(true);enroll(o);var stale=store.claim(1).orElseThrow();Thread.sleep(1100);var fresh=store.claim(5).orElseThrow();assertFalse(worker.run(stale));assertFalse(store.complete(stale));assertEquals("CLOSED",staff.progress(manager,o.request()).state());assertTrue(worker.run(fresh));assertEquals(2,store.read(manager,o.request()).attempts());}
 @Test void sixCrashedLeasesExhaustBudgetAndCannotReopen()throws Exception{var o=pending(false);enroll(o);for(int i=1;i<=6;i++){assertEquals(i,store.claim(1).orElseThrow().attempt());Thread.sleep(1100);}assertTrue(store.claim(1).isEmpty());var j=store.read(manager,o.request());assertEquals("REVIEW",j.state());assertEquals("LEASE_EXHAUSTED",j.lastCode());assertEquals(6,j.attempts());assertEquals(j,store.enroll(manager,o.request(),body(o)));assertEquals(6,count(o.request(),"stock_return_recovery_claim"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_return_recovery_job SET attempts=0,version=version+1 WHERE request_id=?",o.request()));}
 @Test void leaseExpiresAfterRedisOperationRollsBackAckAndCheckpoint()throws Exception{var o=pending(true);enroll(o);var c=store.claim(1).orElseThrow();var steps=new java.util.concurrent.atomic.AtomicInteger();assertThrows(StockReturnRecoveryStore.LostLease.class,()->staff.submit(manager,o.f().ticket(),o.order(),body(o),()->{if(steps.incrementAndGet()==3){try{Thread.sleep(1100);}catch(InterruptedException e){throw new RuntimeException(e);}}store.fence(c);}));assertEquals(3,steps.get());assertEquals(0,count(o.request(),"stock_return_ack"));assertEquals("CLOSED",staff.progress(manager,o.request()).state());assertTrue(worker.run(store.claim(5).orElseThrow()));assertEquals(1,count(o.request(),"stock_return_ack"));}
 @Test void enrollmentAuditFailureIsAtomicAndClaimsAndAuditImmutable(){var o=pending(false);db.execute("ALTER TABLE stock_return_recovery_audit ADD CONSTRAINT queue_enroll_fault CHECK(version<>1) NOT VALID");try{assertThrows(org.springframework.dao.DataAccessException.class,()->store.enroll(manager,o.request(),body(o)));assertEquals(0,count(o.request(),"stock_return_recovery_job"));}finally{db.execute("ALTER TABLE stock_return_recovery_audit DROP CONSTRAINT queue_enroll_fault");}enroll(o);assertTrue(worker.run(store.claim(5).orElseThrow()));for(String t:List.of("stock_return_recovery_audit","stock_return_recovery_claim","stock_return_recovery_job")){assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM "+t+" WHERE request_id=?",o.request()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE "+t+" SET request_id=request_id WHERE request_id=?",o.request()));}}
 @Test void completionRequiresActualAcknowledgedOriginalAndAuditBounds(){var o=pending(false);enroll(o);var c=store.claim(5).orElseThrow();assertThrows(org.springframework.dao.DataAccessException.class,()->store.complete(c));assertEquals("LEASED",store.read(manager,o.request()).state());problem("INVALID_INPUT",()->store.audit(manager,o.request(),1,21));assertThrows(IllegalArgumentException.class,()->store.failed(c,"raw message",true));assertTrue(worker.run(c));}
 @Test void workerAndLeaseGuardRefuseOuterTransactionAndInvalidLimits(){assertThrows(IllegalArgumentException.class,()->new StockReturnRecoveryWorker(store,staff,true,4,1));assertThrows(IllegalArgumentException.class,()->new StockReturnRecoveryWorker(store,staff,true,5,21));var o=pending(false);enroll(o);var c=store.claim(5).orElseThrow();assertThrows(IllegalStateException.class,()->store.fence(c));assertThrows(IllegalStateException.class,()->new TransactionTemplate(transactions).execute(tx->worker.run(c)));assertTrue(worker.run(c));}
}
